package com.railyatra.booking;
import com.railyatra.auth.AuthPrincipal; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/bookings") public class TicketController {private final TicketPdfService tickets;public TicketController(TicketPdfService tickets){this.tickets=tickets;}@GetMapping(value="/{reference}/ticket.pdf",produces=MediaType.APPLICATION_PDF_VALUE) public ResponseEntity<byte[]> download(@AuthenticationPrincipal AuthPrincipal principal,@PathVariable String reference){byte[] pdf=tickets.generate(principal,reference);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=RailYatra-"+reference+".pdf").contentType(MediaType.APPLICATION_PDF).body(pdf);}}
